// Auction's own storage reserve is computed in ../constants — see multiAuctionStorageReserve(ONE_YEAR, N)


// Finish auction: send marketplace commission, seller payout and transfer all domains to the winner
@inline
fun endAuctionSuccess(mutate storage: Storage, jettonWalletAddress: address, maxCommission: uint64, queryId: uint64, additionalTons: coins): void {
    setGasLimitToMaximum();
    val lastBidderAddr: address = storage.lastBidderAddress!;

    var commission: coins = 0;
    if (storage.commissionFactor != 0) {
        commission = min(mulDivFloor(storage.lastBidValue, storage.commissionFactor, COMMISSION_DIVIDER), maxCommission);

        // Send marketplace commission
        createMessage({
            bounce: false,
            value: TONS_JETTON_TRANSFER + TONS_NOTIFY_MARKETPLACE,
            dest: jettonWalletAddress,
            body: SendJettonsMessage<cell> {
                queryId: queryId,
                jettonAmount: commission,
                toAddress: MARKETPLACE_ADDRESS,
                responseAddress: lastBidderAddr,
                forwardTonAmount: TONS_NOTIFY_MARKETPLACE,
                forwardPayload: MARKETPLACE_COMMISSION_NOTIFICATION()
            }
        }).send(SEND_MODE_REGULAR);
    }

    // Send seller payout
    createMessage({
        bounce: false,
        value: TONS_JETTON_TRANSFER + additionalTons,
        dest: jettonWalletAddress,
        body: SendJettonsMessage<cell> {
            queryId: queryId,
            jettonAmount: storage.lastBidValue - commission,
            toAddress: storage.sellerAddress,
            responseAddress: lastBidderAddr,
            forwardTonAmount: additionalTons + 1,
            forwardPayload: MULTIPLE_AUCTION_NOTIFICATION()
        }
    }).send(SEND_MODE_REGULAR);

    // Transfer domains to the auction winner
    val refillFee = domainRefillFee();
    var (domainAddress: slice?, _, found: bool) = storage.domainsDict.sDictGetFirst(267);
    repeat(storage.domainsTotal - 1) {
        createMessage({
            bounce: false,
            value: TONS_PURCHASE_NOTIFICATION + refillFee,
            dest: domainAddress! as address,
            body: NftTransferMessage<cell> {
                queryId: queryId,
                toAddress: lastBidderAddr,
                responseAddress: lastBidderAddr,
                forwardTonAmount: TONS_PURCHASE_NOTIFICATION,
                forwardPayload: BUYER_NOTIFICATION()
            }
        }).send(SEND_MODE_REGULAR);
        (domainAddress, _, found) = storage.domainsDict.sDictGetNext(267, domainAddress!);
    }

    // Last domain transfer with remaining balance
    createMessage({
        bounce: false,
        value: 0,
        dest: domainAddress! as address,
        body: NftTransferMessage<cell> {
            queryId: queryId,
            toAddress: lastBidderAddr,
            responseAddress: lastBidderAddr,
            forwardTonAmount: TONS_PURCHASE_NOTIFICATION,
            forwardPayload: BUYER_NOTIFICATION()
        }
    }).send(SEND_MODE_CARRY_ALL_BALANCE);

    storage.state = STATE_COMPLETED;
    storage.save();
}


// Cancel auction and return all received domains back to the seller if there were no bids
@inline
fun cancelAuction(mutate storage: Storage, queryId: uint64, cancelReason: slice): void {
    setGasLimitToMaximum();

    // Return all domains back to the seller
    val refillFee = domainRefillFee();
    var (domainAddress: slice?, domainReceived: slice?, found: bool) = storage.domainsDict.sDictGetFirst(267);
    while(found) {
        if (domainReceived!.bitsEqual(BIT_TRUE_SLICE())) {
            createMessage({
                bounce: false,
                value: refillFee,
                dest: domainAddress! as address,
                body: NftTransferMessage<cell> {
                    queryId: queryId,
                    toAddress: storage.sellerAddress,
                    responseAddress: storage.sellerAddress,
                    forwardTonAmount: 1,
                    forwardPayload: null
                }
            }).send(SEND_MODE_REGULAR);
        }
        (domainAddress, domainReceived, found) = storage.domainsDict.sDictGetNext(267, domainAddress!);
    }

    // Notify seller and send remaining balance
    createMessage({
        bounce: false,
        value: 0,
        dest: storage.sellerAddress,
        body: CommentMessage { comment: cancelReason }
    }).send(SEND_MODE_CARRY_ALL_BALANCE);

    // Update auction state
    storage.state = STATE_CANCELLED;
    storage.endTime = blockchain.now();
    storage.save();
}


fun getBalanceToReserve(auctionStarted: bool, domainsNumber: uint8): coins {
    val storageReserve: coins = multiAuctionStorageReserve(ONE_YEAR, domainsNumber);  // auction's own 1-year storage rent
    if (auctionStarted) {
        // finalize: jetton commission+payout + per domain (buyer notification + domain refill + endAuctionSuccess loop compute)
        return TONS_JETTON_TRANSFER * 2 + TONS_NOTIFY_MARKETPLACE + (TONS_PURCHASE_NOTIFICATION + domainRefillFee() + gasFee(GAS_AUCTION_FINALIZE_PER_DOMAIN)) * domainsNumber + storageReserve;
    }
    // cancel per domain: domain refill (held domains may have drained below their 1-TON reserve) + loop compute
    val balanceToReserve: coins = (domainRefillFee() + gasFee(GAS_AUCTION_CANCEL_PER_DOMAIN)) * domainsNumber + storageReserve;
    if (contract.getOriginalBalance() < balanceToReserve) {
        return storageReserve;
    }
    return balanceToReserve;
}


fun onBouncedMessage(in: InMessageBounced): void {
    // Forward all bounced messages to the seller
    if (in.valueCoins > TONS_MIN_EXCESS) {
        var storage: Storage = lazy Storage.load();
        createMessage({
            bounce: true,
            value: 0,
            dest: storage.sellerAddress,
            body: ExcessesMessage { queryId: 0 }    
        }).send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
    }
}


fun onInternalMessage(in: InMessage) {
    forceSameWorkchain(in.senderAddress);

    var storage: Storage = lazy Storage.load();

    // Handle admin messages for contract management
    val allowAdminCommands: bool = storage.state != STATE_ACTIVE || storage.endTime + 600 < blockchain.now();
    handleAdminMessage(in.senderAddress, in.body, Permissions {
        allowChangeCode: allowAdminCommands,
        allowChangeData: allowAdminCommands,
        allowSendAnyMessage: allowAdminCommands,
        allowWithdrawTon: true,
    });

    var msg = lazy AllowedMessage.fromSlice(in.body);

    match (msg) {
        // Activate the auction when deployed by marketplace
        DeployAndSetWalletMessage => {
            if (storage.state == STATE_UNINIT) {
                assert(in.senderAddress == MARKETPLACE_ADDRESS) throw EXC_INCORRECT_SENDER;
                var storage2: StorageDs2 = lazy storage.ds2.load();
                storage2.jettonWalletAddress = msg.jettonWalletAddress;
                storage.ds2 = storage2.toCell();
                storage.state = STATE_ACTIVE;
                storage.save();
            }
            return;
        }

        // Seller sends domain to the auction contract
        NftOwnershipAssignedMessage => {
            try {
                assert(storage.state == STATE_ACTIVE) throw EXC_DEAL_NOT_ACTIVE;
                var (_, found) = storage.domainsDict.sDictGet(267, in.senderAddress as slice);
                assert(found) throw EXC_INCORRECT_DOMAIN;

                storage.domainsDict.sDictSet(267, in.senderAddress as slice, BIT_TRUE_SLICE());
                storage.domainsReceived += 1;

                // If all domains were received, activate the auction and notify seller
                if (storage.domainsReceived == storage.domainsTotal) {
                    val tonsToReserve: coins = getBalanceToReserve(false, storage.domainsTotal);
                    reserveToncoinsOnBalance(tonsToReserve, RESERVE_MODE_EXACT_AMOUNT);

                    // Notify seller that auction is ready
                    createMessage({
                        bounce: false,
                        value: 0,
                        dest: storage.sellerAddress,
                        body: CommentMessage { comment: "Multiple auction on webdom.market is active".literalSlice() }
                    }).send(SEND_MODE_CARRY_ALL_BALANCE);
                }
                storage.save();
                return;
            } catch (e, _) {
                returnNftToSender(in.senderAddress, msg, e);
            }
        }

        // Handle jetton bid (including DeDust swap payouts)
        JettonsTransferNotificationMessage<SerializableSlice> => {
            var fromAddress = msg.fromAddress;

            // If jettons were received by DeDust swap, extract real sender from payload
            if (msg.forwardPayload is Cell<SerializableSlice>) {
                msg.forwardPayload = msg.forwardPayload.load();
            }
            if (msg.forwardPayload.remainingBitsCount() == 267) {
                fromAddress = address.fromSlice(msg.forwardPayload);
            }

            var storage2: StorageDs2 = lazy storage.ds2.load();

            try {
                assert(storage2.jettonWalletAddress != null && in.senderAddress == storage2.jettonWalletAddress!) throw EXC_INCORRECT_SENDER;  // check that jettons were received from the correct wallet
                val jettonWalletAddr: address = storage2.jettonWalletAddress!;

                if (storage.isDeferred && (blockchain.now() < storage.startTime) && (storage.domainsReceived == storage.domainsTotal)) {  // start auction if it was deferred
                    storage.endTime = blockchain.now() + storage.endTime - storage.startTime;
                    storage.startTime = blockchain.now();
                    storage.isDeferred = false;
                } else {  // otherwise, check if auction is active
                    assert((blockchain.now() >= storage.startTime) && (blockchain.now() < storage.endTime) && (storage.domainsReceived == storage.domainsTotal)) throw EXC_DEAL_NOT_ACTIVE;
                }

                val tonsToReserve: coins = getBalanceToReserve(true, storage.domainsTotal);
                var requiredGas: coins = tonsToReserve + TONS_JETTON_TRANSFER + gasFee(GAS_AUCTION_BID_PROCESSING);  // tonsToReserve + the bid-handler compute
                if (msg.transferredJettons > storage2.maxBidValue) {
                    requiredGas += TONS_JETTON_TRANSFER;
                }

                assert(in.valueCoins >= requiredGas) throw EXC_OUT_OF_GAS;

                // Calculate minimal bid considering absolute and relative increments
                var nextMinBidValue: coins = max(
                    max(storage.lastBidValue + 1000, storage.minBidValue),
                    mulDivFloor(storage.lastBidValue, storage.minBidIncrement, BID_INCREMENT_DIVIDER)
                );
                assert(msg.transferredJettons >= nextMinBidValue) throw EXC_BID_TOO_LOW;

                // Extend auction end time if close to finish (bounded by domain expiration)
                if (storage.endTime <= blockchain.now() + storage.timeIncrement) {
                    storage.endTime = min(blockchain.now() + storage.timeIncrement, storage.lastDomainRenewalTime + ONE_YEAR - ONE_DAY);
                }

                val prevTonBalance = contract.getOriginalBalance() - in.valueCoins;
                if (storage.lastBidValue != 0) {
                    // Return jettons to the previous bidder
                    createMessage({
                        bounce: false,
                        value: prevTonBalance,  // всегда больше TONS_JETTON_TRANSFER
                        dest: jettonWalletAddr,
                        body: SendJettonsMessage<cell> {
                            queryId: msg.queryId,
                            jettonAmount: storage.lastBidValue,
                            toAddress: storage.lastBidderAddress!,
                            responseAddress: storage.lastBidderAddress!,
                            forwardTonAmount: 1,
                            forwardPayload: OUTBID_NOTIFICATION()
                        }
                    }).send(SEND_MODE_REGULAR);
                }
                else if (prevTonBalance > TONS_MIN_EXCESS) {
                    // After the first bid, the last bidder maintains the auction's TON reserve, so we return seller's initial reserve
                    createMessage({
                        bounce: true,
                        value: prevTonBalance,
                        dest: storage.sellerAddress,
                        body: ExcessesMessage { queryId: msg.queryId }
                    }).send(SEND_MODE_REGULAR);
                }

                storage.lastBidTime = blockchain.now();
                storage.lastBidderAddress = fromAddress;

                if (msg.transferredJettons >= storage2.maxBidValue) {
                    if (msg.transferredJettons > storage2.maxBidValue) {
                        // Return excess jettons
                        createMessage({
                            bounce: false,
                            value: TONS_JETTON_TRANSFER,
                            dest: jettonWalletAddr,
                            body: SendJettonsMessage<cell> {
                                queryId: msg.queryId,
                                jettonAmount: msg.transferredJettons - storage2.maxBidValue,
                                toAddress: fromAddress,
                                responseAddress: fromAddress,
                                forwardTonAmount: 1,
                                forwardPayload: EXCESSES_NOTIFICATION()
                            }
                        }).send(SEND_MODE_REGULAR);
                    }

                    storage.lastBidValue = storage2.maxBidValue;
                    storage.endTime = blockchain.now();

                    endAuctionSuccess(mutate storage, storage2.jettonWalletAddress!, storage2.maxCommission, msg.queryId, 0);
                    return;
                } else {
                    // Reserve TONs to safely finalize the auction and pay storage fees
                    reserveToncoinsOnBalance(tonsToReserve, RESERVE_MODE_EXACT_AMOUNT);
                    createMessage({
                        bounce: false,
                        value: 0,
                        dest: fromAddress,
                        body: CommentMessage { comment: "Bid placed successfully".literalSlice() }
                    }).send(SEND_MODE_CARRY_ALL_BALANCE);
                }

                storage.lastBidValue = msg.transferredJettons;
                storage.save();
                return;
            } catch (e, _) {
                // Return jettons on error
                returnJettonsToSender(in.senderAddress, msg, e);
            }
        }

        // Handle domain renewal request
        RenewDomainMessage => {
            assert(in.valueCoins >= TONS_RENEW_REQUEST + renewDomainFee() * storage.domainsTotal) throw EXC_OUT_OF_GAS;
            assert(storage.lastDomainRenewalTime + ONE_YEAR - ONE_DAY >= blockchain.now()) throw EXC_DOMAIN_EXPIRED;

            val tonsToReserve: coins = getBalanceToReserve(storage.lastBidValue > 0, storage.domainsTotal);
            reserveToncoinsOnBalance(tonsToReserve, RESERVE_MODE_EXACT_AMOUNT);

            var (domainAddress: slice?, _, found: bool) = storage.domainsDict.sDictGetFirst(267);
            while (found) {
                createMessage({
                    bounce: false,
                    value: renewDomainFee(),
                    dest: domainAddress! as address
                }).send(SEND_MODE_REGULAR);
                (domainAddress, _, found) = storage.domainsDict.sDictGetNext(267, domainAddress!);
            }

            // Send renewal fee to the marketplace
            createMessage({
                bounce: false,
                value: 0,
                dest: MARKETPLACE_ADDRESS,
                body: RenewalFeeMessage { queryId: msg.queryId, ownerAddress: storage.sellerAddress }
            }).send(SEND_MODE_CARRY_ALL_BALANCE);

            storage.lastDomainRenewalTime = blockchain.now();
            storage.save();
            return;
        }

        // Handle hot promotion
        MakeHotMessage => {
            handleMakeHot<Storage>(mutate storage, msg.promotionUntil, msg.queryId, in.senderAddress);
            return;
        }

        // Handle colored promotion
        MakeColoredMessage => {
            handleMakeColored<Storage>(mutate storage, msg.promotionUntil, msg.queryId, in.senderAddress);
            return;
        }

        // Ignore excess
        ExcessesMessage => {
            return;
        }

        else => {
            var (op: uint32, queryId: uint64) = loadOpAndQueryId(mutate in.body);
            if (op == OP_STOP_AUCTION || op == OP_CANCEL_DEAL) {
                if (storage.lastBidValue == 0) {  // Cancel auction if it hasn't started yet
                    assert(in.senderAddress == storage.sellerAddress || in.senderAddress == ADMIN_ADDRESS) throw EXC_INCORRECT_SENDER;
                    cancelAuction(mutate storage, 0, "Multiple auction on webdom.market was cancelled".literalSlice());
                    return;
                } else if (storage.endTime <= blockchain.now()) {  // End auction if it is over
                    var additionalTons: coins;
                    if (in.senderAddress == storage.sellerAddress) {
                        additionalTons = in.valueCoins;  // Seller doesn't pay gas fees for finalizing the auction
                    } else {
                        assert((storage.lastBidderAddress != null && in.senderAddress == storage.lastBidderAddress!) || in.senderAddress == ADMIN_ADDRESS) throw EXC_INCORRECT_SENDER;
                        additionalTons = 0;
                    }
                    var storage2: StorageDs2 = lazy storage.ds2.load();
                    endAuctionSuccess(mutate storage, storage2.jettonWalletAddress!, storage2.maxCommission, 0, additionalTons);
                    return;
                } else {
                    throw EXC_AUCTION_NOT_ENDED;
                }
            }
            throw EXC_UNSUPPORTED_OP;
        }
    }
}

fun onExternalMessage(inMsg: slice) {
    var storage: Storage = lazy Storage.load();

    if (storage.state != STATE_ACTIVE) {
        throw EXC_DEAL_NOT_ACTIVE;
    }

    // Allow anyone to finalize ended auctions via external message
    if (blockchain.now() >= storage.endTime) {
        var opCode = inMsg.loadUint(32);
        if (opCode != OP_CANCEL_DEAL) {
            throw EXC_UNSUPPORTED_OP;
        }
        var queryId: uint64 = inMsg.loadUint(64);

        if (storage.lastBidValue == 0) {  // No one participated in the auction
            assert(contract.getOriginalBalance() >= (domainRefillFee() + gasFee(GAS_AUCTION_CANCEL_PER_DOMAIN)) * storage.domainsReceived) throw EXC_OUT_OF_GAS;
            acceptExternalMessage();
            cancelAuction(mutate storage, queryId, "Multiple auction on webdom.market has ended without bids".literalSlice());
        } else {  // Auction finished successfully
            acceptExternalMessage();
            var storage2: StorageDs2 = lazy storage.ds2.load();
            endAuctionSuccess(mutate storage, storage2.jettonWalletAddress!, storage2.maxCommission, queryId, 0);
        }

        return;
    }

    throw 0xfffe;
}


get fun get_storage_data() {
    var storage: Storage = lazy Storage.load();
    var storage2: StorageDs2 = lazy storage.ds2.load();
    return (
        storage.sellerAddress,
        storage.domainsDict,
        storage.domainsTotal,
        storage.domainsReceived,
        storage.state,
        storage2.maxBidValue,
        storage.commissionFactor,
        storage.startTime,
        storage.lastDomainRenewalTime,
        storage.endTime,
        storage.lastBidderAddress == null ? (createAddressNone() as address) : storage.lastBidderAddress!,
        storage.minBidValue,
        storage.minBidIncrement,
        storage.timeIncrement,
        storage.lastBidValue,
        storage.lastBidTime,
        storage2.maxCommission,
        storage2.jettonWalletAddress == null ? (createAddressNone() as address) : storage2.jettonWalletAddress!,
        storage.isDeferred && (blockchain.now() < storage.startTime),
        storage.hotUntil,
        storage.coloredUntil,
        storage2.jettonMinterAddress,
        contract.getCode().hash()
    );
}


// Legacy methods from https://github.com/getgems-io/nft-contracts/blob/main/packages/contracts/sources/nft-auction-v4r1.func
get fun get_auction_data_v4() {
    var storage = lazy Storage.load();
    var storage2 = lazy storage.ds2.load();

    val (domainAddress, _, _) = storage.domainsDict.sDictGetFirst(267);
    if (storage.isDeferred && (blockchain.now() < storage.startTime)) {
        storage.endTime = blockchain.now() + storage.endTime - storage.startTime;
        storage.startTime = blockchain.now();
    }

    return (
        storage.state != STATE_UNINIT,                 // Int1
        storage.state > STATE_ACTIVE,                  // Int1
        storage.endTime,                               // Uint32
        MARKETPLACE_ADDRESS,                           // MsgAddressStd
        domainAddress,                                 // MsgAddressStd
        storage.sellerAddress,                         // MsgAddressStd
        storage.lastBidValue,                          // Coins
        storage.lastBidderAddress == null ? (createAddressNone() as address) : storage.lastBidderAddress!,  // MsgAddressStd
        (storage.minBidIncrement - 1000) / 10,         // Uint7
        MARKETPLACE_ADDRESS,                           // MsgAddressStd
        storage.commissionFactor, COMMISSION_DIVIDER,  // Uint16, Uint16
        BURN_ADDRESS,                                  // MsgAddressStd
        0, 1,                                          // Uint32, Uint32
        storage2.maxBidValue,                          // Coins
        storage.minBidValue,                           // Coins
        storage.startTime,                             // Uint32
        storage.lastBidTime,                           // Uint32
        storage.state == STATE_CANCELLED,              // Int1
        storage.timeIncrement,                         // Uint17
        0,                                             // Uint64
        storage2.jettonWalletAddress == null ? (createAddressNone() as address) : storage2.jettonWalletAddress!,  // MsgAddressStd
        storage2.jettonMinterAddress,                  // MsgAddressStd
        0,                                             // Uint1
        0                                              // Uint256
    )
}

import "@stdlib/gas-payments"
import "constants"

/**
  Runtime fee helpers — compute each TON budget from CURRENT on-chain prices at call time, so the
  value attached to a message always matches the real cost as prices change.

  Three cost types, each from its own config param:
    - compute gas    -> calculateGasFee     (config 21)
    - message forward-> calculateForwardFee  (config 25)
    - storage rent   -> calculateStorageFee  (config 18)

  Inputs are MEASURED units (sized from GasResearch*.spec.ts). We pass a measured contract size
  rather than calling CDATASIZE at runtime (~7k gas/call): size is fixed per compiled contract
  (asserted in SaleGasSize.spec.ts), only price is dynamic.

  Excluded (no live price to track): the jetton wallet floor (TONS_JETTON_TRANSFER) and marketplace fees.
*/

/// Fee for `gasUnits` of compute gas at the current gas price.
@inline
fun gasFee(gasUnits: int): coins {
    return calculateGasFee(WORKCHAIN as int8, gasUnits);
}

/// Forward fee for one message of the given body size at the current forward price.
/// Pass a conservative single-cell size; lump_price dominates for small messages.
@inline
fun forwardFee(bits: int, cells: int): coins {
    return calculateForwardFee(WORKCHAIN as int8, bits, cells);
}

/// Storage rent to keep a contract of (bits, cells) alive for `seconds` at the current storage price.
@inline
fun storageFee(seconds: int, bits: int, cells: int): coins {
    return calculateStorageFee(WORKCHAIN as int8, seconds, bits, cells);
}


/* ---- Domain (TON DNS item / TG username) fee helpers ---- */
// Measured (TransferGas.spec.ts) at 50 DNS records, code+data, per item type:
//   TON DNS domain : 10,855 transfer gas ; 195 cells / 28,232 bits
//   TG username    :  9,526 transfer gas ; 199 cells / 33,359 bits
// The item keeps >= min_tons_for_storage (~1 TON) itself — its transfer handler throws 402 rather than
// drop below that reserve (domain.fc:92). So a plain transfer pays only compute + its two onward
// forwards; storage is funded by the item's own reserve and yearly by renewDomainFee (.ton only).
// A transfer that finds the item drained below its reserve must REFILL it — see domainRefillFee().
const DOMAIN_STORAGE_CELLS: int = 200;     // .ton domain, 50 records (195 measured), padded — for renew/refill
const DOMAIN_STORAGE_BITS: int  = 34000;   // >= 28,232
// Measured transfer_ownership compute is ~11k gas (domain) / ~9.5k (TG); ~1.5x margin.
const DOMAIN_TRANSFER_GAS: int  = 16000;
const DOMAIN_RENEW_GAS: int     = 8000;    // ~1.6x measured renew/fill-up compute (~4.8k)
const DOMAIN_MSG_BITS: int      = 1023;    // conservative single-cell message
const DOMAIN_MSG_CELLS: int     = 1;

/// Value for an NFT (domain / TG username) transfer: transfer compute + its two onward forwards
/// (ownership_assigned + excess). No storage — the item keeps its own ~1-TON reserve; tight
/// fixed-value paths top it up via domainRefillFee().
@inline
fun nftTransferFee(): coins {
    return gasFee(DOMAIN_TRANSFER_GAS) + forwardFee(DOMAIN_MSG_BITS, DOMAIN_MSG_CELLS) * 2;
}

/// One year of a domain item's storage rent at the live price. Keeps the item funded above its reserve:
/// the storage top-up in a renewal, and the refill buffer on fixed-value transfers.
@inline
fun domainStorageYear(): coins {
    return storageFee(ONE_YEAR, DOMAIN_STORAGE_BITS, DOMAIN_STORAGE_CELLS);
}

/// Value for moving a domain with a FIXED amount (no CARRY_ALL) that may have drained below its
/// reserve: transfer cost + one year of storage to refill it, so its 402 reserve check passes.
@inline
fun domainRefillFee(): coins {
    return nftTransferFee() + domainStorageYear();
}

/// Value for a domain renewal: one year of storage (≤50 records) + renew compute + one forward.
/// Renewal applies ONLY to .ton domains.
@inline
fun renewDomainFee(): coins {
    return domainStorageYear()
         + gasFee(DOMAIN_RENEW_GAS)
         + forwardFee(DOMAIN_MSG_BITS, DOMAIN_MSG_CELLS);
}

// change_dns_record on a domain / TG username item. Measured (ChangeDnsRecordGas.spec.ts) at ~50
// records on a .ton domain. Worst case across the records we send (address record and the max-length
// `links` text record): ~11k compute gas; the max link record adds ~5 cells / ~1.4k bits to the item.
const DNS_CHANGE_RECORD_GAS: int = 12500;   // ~1.1x measured worst-case compute

/// Value to attach to a change_dns_record message: the item's compute to store the record plus one
/// year of storage rent for the record it adds (the item's change_dns_record handler sends nothing
/// onward, so there are no further forwards to fund). The message's own forward fee is added by the
/// caller via sendAndEstimateFee.
@inline
fun changeDnsRecordValue(): coins {
    return gasFee(DNS_CHANGE_RECORD_GAS);
}

/* GLOBAL OP-CODES */

// Common
const OP_COMMENT: uint32                = 0x00000000;
const OP_GET_STATIC_DATA: uint32        = 0x2fcb26a2;
const OP_REPORT_STATIC_DATA: uint32     = 0x8b771735;
const OP_GET_STORAGE_DATA: uint32       = 0x5b88e5cc;
const OP_REPORT_STORAGE_DATA: uint32    = 0xaab4a8ef;
